// Написан вручную (UI + API + восстановление профиля — генератор так не умеет).
// spec: .qa/e2e/specs/questionnaire.md 2.1 · кейс .qa/tests/questionnaire/QN-04 · тикеты #d20b68, #a85b92
// @data: new09 нажимает «דילוג» на Q-03 (self_definition = null); в finally self_definition и onboarding_step
// возвращаются к исходным через PATCH profiles (своя строка, RLS own). new09 не используется другими автотестами.
// Не проверен на живой странице (записан 10.11 без прогона) — сверить при первом /qa-regress:
// адрес сообщества (/rooms), имя кнопки «דילוג», колонки profiles.
// Проект data идёт на десктопе — окно iPhone 13 Mini (WebKit) открывается явно через iphoneAs.
import { test, expect } from '@playwright/test';
import { captureApi, restGet, type Api, type Row } from '../_shared/api';
import { iphoneAs, closeAs } from '../stories-viewer/viewer-helpers';

const ROLE = 'new09';

function patchProfile(api: Api, data: Row) {
  return api.page.request.patch(`${api.base}/rest/v1/profiles?id=eq.${api.userId}`, {
    headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', Prefer: 'return=representation' },
    data,
    failOnStatusCode: false,
  });
}

test.describe('מנוע שאלונים מותאמי קהל — пропуск Q-03', () => {
  test.describe.configure({ timeout: 90_000 });

  test('Пропуск Q-03 «דילוג» → «הקהל שלך לא הוגדר», story_feed 400 audience_missing @iphone @data (#d20b68)', async ({ browser }) => {
    const page = await iphoneAs(browser, ROLE);
    const api = await captureApi(page, '/');
    const before = await restGet(api, `profiles?id=eq.${api.userId}&select=self_definition,onboarding_step`);
    expect(before.status(), `profiles: ${await before.text()}`).toBe(200);
    const original = ((await before.json()) as Row[])[0];
    expect(original, 'строка профиля new09').toBeTruthy();
    try {
      await page.goto('/self-definition');
      const patched = page.waitForResponse((r) => r.url().includes('/rest/v1/profiles') && r.request().method() === 'PATCH');
      await page.getByRole('button', { name: 'דילוג', exact: true }).click();
      expect((await patched).ok(), 'PATCH profiles после «דילוג»').toBeTruthy();

      // #a85b92 AC 7 / #d20b68 AC 6: без аудитории — сообщение вместо ленты.
      await page.goto('/rooms');
      await expect(page.getByText('הקהל שלך לא הוגדר')).toBeVisible();
      await expect(page.getByText(/דילגת על שאלת ההגדרה העצמית/)).toBeVisible();

      // Сервер: story_feed отвечает ошибкой audience_missing.
      const feed = await restGet(api, 'story_feed?select=id&limit=1');
      expect(feed.status()).toBe(400);
      expect(await feed.text()).toContain('audience_missing');
    } finally {
      const restore = await patchProfile(api, {
        self_definition: original.self_definition ?? null,
        onboarding_step: original.onboarding_step ?? null,
      });
      expect(restore.ok(), `восстановление профиля new09: ${await restore.text()}`).toBeTruthy();
      await closeAs(page, ROLE);
    }
  });
});
